 "Process Instagram Top Videos": "const items = $input.all().map(i => i.json);\nconst client = $('Loop Over Clients').item.json.client_name;\nconst now = new Date();\nconst oneWeekAgo = new Date(now - 7 * 24 * 60 * 60 * 1000);\nconst oneMonthAgo = new Date(now - 30 * 24 * 60 * 60 * 1000);\n\nfunction parseDate(p) {\n  const ts = p.taken_at || p.timestamp || p.date;\n  if (!ts) return new Date(0);\n  let d;\n  if (typeof ts === 'number') {\n    d = ts > 1e12 ? new Date(ts) : new Date(ts * 1000);\n  } else {\n    d = new Date(ts);\n  }\n  if (isNaN(d.getTime()) || d < new Date('2015-01-01') || d > new Date(now.getTime() + 86400000)) return new Date(0);\n  return d;\n}\n\nconst withDates = items\n  .filter(p => p.id || p.shortCode || p.url)\n  .map(p => ({ ...p, _date: parseDate(p), _views: p.videoPlayCount || p.playCount || p.videoViewCount || 0 }));\n\nconst weekPosts = withDates.filter(p => p._date.getTime() > 0 && p._date >= oneWeekAgo);\nconst monthPosts = withDates.filter(p => p._date.getTime() > 0 && p._date >= oneMonthAgo);\nconst byViews = (a, b) => b._views - a._views;\n\nconst top3Week = [...weekPosts].sort(byViews).slice(0, 3);\nconst top5Month = [...monthPosts].sort(byViews).slice(0, 5);\n\nconst toRow = (p, period, rank) => ({\n  scraped_date: now.toISOString().split('T')[0],\n  client_name: client, platform: 'instagram', period, rank,\n  caption: (p.caption || p.text || '').substring(0, 200),\n  thumbnail_url: '', video_url: p.url || p.webVideoUrl || '',\n  views: p._views, likes: p.likesCount || 0,\n  comments: p.commentsCount || 0, shares: p.sharesCount || p.shareCount || 0\n});\n\nconst emptyWeekRow = {\n  scraped_date: now.toISOString().split('T')[0],\n  client_name: client, platform: 'instagram', period: 'week', rank: 0,\n  caption: 'No new posts in the last 7 days',\n  thumbnail_url: '', video_url: '',\n  views: 0, likes: 0, comments: 0, shares: 0\n};\n\nconst weekRows = top3Week.length > 0\n  ? top3Week.map((p, i) => toRow(p, 'week', i + 1))\n  : [emptyWeekRow];\n\nconst rows = [\n  ...weekRows,\n  ...top5Month.map((p, i) => toRow(p, 'month', i + 1))\n];\nreturn [{ json: { rows, platform: 'instagram' } }];",
 "Process TikTok Top Videos": "const items = $input.all();\nconst client = $('Loop Over Clients').item.json.client_name;\nconst now = new Date();\nconst oneWeekAgo = new Date(now - 7 * 24 * 60 * 60 * 1000);\nconst oneMonthAgo = new Date(now - 30 * 24 * 60 * 60 * 1000);\n\nconst posts = items.map(i => i.json).filter(p => p.id);\nconst withDates = posts.map(p => {\n  const rawTime = p.createTime || p.createTimestamp || 0;\n  let _date = new Date(0);\n  if (rawTime) {\n    _date = rawTime > 1e12 ? new Date(rawTime) : new Date(rawTime * 1000);\n    if (isNaN(_date.getTime()) || _date < new Date('2015-01-01') || _date > new Date(now.getTime() + 86400000)) {\n      _date = new Date(0);\n    }\n  }\n  return { ...p, _date };\n});\n\nconst weekPosts = withDates.filter(p => p._date.getTime() > 0 && p._date >= oneWeekAgo);\nconst monthPosts = withDates.filter(p => p._date.getTime() > 0 && p._date >= oneMonthAgo);\nconst byPlays = (a, b) => (b.playCount || 0) - (a.playCount || 0);\n\nconst top3Week = [...weekPosts].sort(byPlays).slice(0, 3);\nconst top5Month = [...monthPosts].sort(byPlays).slice(0, 5);\n\nconst toRow = (p, period, rank) => ({\n  scraped_date: now.toISOString().split('T')[0],\n  client_name: client, platform: 'tiktok', period, rank,\n  caption: (p.text || '').substring(0, 200),\n  thumbnail_url: '', video_url: p.webVideoUrl || '',\n  views: p.playCount || 0, likes: p.diggCount || 0,\n  comments: p.commentCount || 0, shares: p.shareCount || 0\n});\n\nconst emptyWeekRow = {\n  scraped_date: now.toISOString().split('T')[0],\n  client_name: client, platform: 'tiktok', period: 'week', rank: 0,\n  caption: 'No new posts in the last 7 days',\n  thumbnail_url: '', video_url: '',\n  views: 0, likes: 0, comments: 0, shares: 0\n};\n\nconst weekRows = top3Week.length > 0\n  ? top3Week.map((p, i) => toRow(p, 'week', i + 1))\n  : [emptyWeekRow];\n\nconst rows = [\n  ...weekRows,\n  ...top5Month.map((p, i) => toRow(p, 'month', i + 1))\n];\nreturn rows.length > 0 ? [{ json: { rows, platform: 'tiktok' } }] : [{ json: { rows: [], platform: 'tiktok' } }];",
 "Process YouTube Top Videos": "const data = $input.first().json;\nconst videos = data.items || [];\nconst client = $('Loop Over Clients').item.json.client_name;\nconst now = new Date();\nconst oneWeekAgo = new Date(now - 7 * 24 * 60 * 60 * 1000);\n\nconst withDates = videos.map(v => ({\n  ...v,\n  _date: new Date((v.snippet && v.snippet.publishedAt) || 0),\n  _views: parseInt((v.statistics && v.statistics.viewCount) || 0)\n}));\n\nconst weekPosts = withDates.filter(v => v._date >= oneWeekAgo);\nconst monthPosts = withDates;\nconst byViews = (a, b) => b._views - a._views;\n\nconst top3Week = [...weekPosts].sort(byViews).slice(0, 3);\nconst top5Month = [...monthPosts].sort(byViews).slice(0, 5);\n\nconst toRow = (v, period, rank) => ({\n  scraped_date: now.toISOString().split('T')[0],\n  client_name: client, platform: 'youtube', period, rank,\n  caption: ((v.snippet && v.snippet.title) || '').substring(0, 200),\n  thumbnail_url: '', video_url: 'https://www.youtube.com/watch?v=' + v.id,\n  views: parseInt((v.statistics && v.statistics.viewCount) || 0),\n  likes: parseInt((v.statistics && v.statistics.likeCount) || 0),\n  comments: parseInt((v.statistics && v.statistics.commentCount) || 0), shares: 0\n});\n\nconst emptyWeekRow = {\n  scraped_date: now.toISOString().split('T')[0],\n  client_name: client, platform: 'youtube', period: 'week', rank: 0,\n  caption: 'No new posts in the last 7 days',\n  thumbnail_url: '', video_url: '',\n  views: 0, likes: 0, comments: 0, shares: 0\n};\n\nconst weekRows = top3Week.length > 0\n  ? top3Week.map((v, i) => toRow(v, 'week', i + 1))\n  : [emptyWeekRow];\n\nconst rows = [\n  ...weekRows,\n  ...top5Month.map((v, i) => toRow(v, 'month', i + 1))\n];\nreturn rows.length > 0 ? [{ json: { rows, platform: 'youtube' } }] : [{ json: { rows: [], platform: 'youtube' } }];",
 "Unpack Rows": "const client = $('Loop Over Clients').item.json.client_name;\nlet igRows = [];\ntry { igRows = $('Process Instagram Top Videos').first().json.rows || []; } catch(e) {}\nlet ttRows = [];\ntry { ttRows = $('Process TikTok Top Videos').first().json.rows || []; } catch(e) {}\nlet ytRows = [];\ntry { ytRows = $input.first().json.rows || []; } catch(e) {}\n// Guard against stale node references: when a platform branch errors and is\n// skipped this iteration, $('...') can return the previous client's run.\nconst all = [...igRows, ...ttRows, ...ytRows].filter(r => r.client_name === client);\nif (all.length === 0) return [{ json: { skip: true } }];\nreturn all.map(r => ({ json: { ...r, caption: (r.caption || '').replace(/\\s+/g, ' ').trim() } }));"
